<?php
// Este arquivo cuida somente da comunicação entre o JavaScript e o banco de dados.
require_once 'conexao.php';
header('Content-Type: application/json; charset=utf-8');
function resposta($ok, $dados = [], $codigo = 200) { http_response_code($codigo); echo json_encode(['ok'=>$ok] + $dados, JSON_UNESCAPED_UNICODE); exit; }
function entrada() { return json_decode(file_get_contents('php://input'), true) ?? $_POST; }
function usuarioLogado() { if (empty($_SESSION['usuario'])) resposta(false,['mensagem'=>'Faça login para continuar.'],401); return $_SESSION['usuario']; }
function administrador() { $u=usuarioLogado(); if (!$u['is_admin']) resposta(false,['mensagem'=>'Acesso permitido somente ao administrador.'],403); return $u; }
$acao = $_GET['acao'] ?? '';
try {
 if ($acao === 'menu') { $itens=$pdo->query('SELECT id,nome,descricao,categoria,preco FROM cardapio WHERE ativo=1 ORDER BY categoria,nome')->fetchAll(); resposta(true,['itens'=>$itens]); }
 if ($acao === 'taxa') { $arquivo=__DIR__.'/taxa.txt'; $taxa=file_exists($arquivo)?(float)file_get_contents($arquivo):7; resposta(true,['taxa'=>$taxa]); }
 if ($acao === 'cadastro') { $d=entrada(); if(strlen(trim($d['nome']??''))<3 || !filter_var($d['email']??'',FILTER_VALIDATE_EMAIL) || strlen($d['senha']??'')<4 || empty($d['endereco'])) resposta(false,['mensagem'=>'Preencha nome, e-mail válido, senha (mínimo 4 caracteres) e endereço.'],400); $s=$pdo->prepare('INSERT INTO usuarios(nome,email,senha,endereco) VALUES(?,?,?,?)'); try{$s->execute([trim($d['nome']),strtolower(trim($d['email'])),password_hash($d['senha'],PASSWORD_DEFAULT),trim($d['endereco'])]);}catch(PDOException $e){resposta(false,['mensagem'=>'Este e-mail já está cadastrado.'],400);} $_SESSION['usuario']=['id'=>(int)$pdo->lastInsertId(),'nome'=>$d['nome'],'email'=>$d['email'],'endereco'=>$d['endereco'],'is_admin'=>0]; resposta(true,['mensagem'=>'Cadastro realizado.']); }
 if ($acao === 'login') { $d=entrada(); $s=$pdo->prepare('SELECT * FROM usuarios WHERE email=?'); $s->execute([strtolower(trim($d['email']??''))]); $u=$s->fetch(); if(!$u || !password_verify($d['senha']??'', $u['senha'])) resposta(false,['mensagem'=>'E-mail ou senha incorretos.'],401); $_SESSION['usuario']=['id'=>(int)$u['id'],'nome'=>$u['nome'],'email'=>$u['email'],'endereco'=>$u['endereco'],'is_admin'=>(int)$u['is_admin']]; resposta(true,['usuario'=>$_SESSION['usuario']]); }
 if ($acao === 'sair') { session_destroy(); resposta(true); }
 if ($acao === 'eu') { resposta(true,['usuario'=>$_SESSION['usuario']??null]); }
 if ($acao === 'editar-conta') { $u=usuarioLogado(); $d=entrada(); $s=$pdo->prepare('UPDATE usuarios SET nome=?,email=?,endereco=? WHERE id=?'); try{$s->execute([trim($d['nome']),strtolower(trim($d['email'])),trim($d['endereco']),$u['id']]);}catch(PDOException $e){resposta(false,['mensagem'=>'E-mail já utilizado.'],400);} $_SESSION['usuario']=array_merge($u,['nome'=>$d['nome'],'email'=>$d['email'],'endereco'=>$d['endereco']]); resposta(true,['mensagem'=>'Dados atualizados.']); }
 if ($acao === 'excluir-conta') { $u=usuarioLogado(); $s=$pdo->prepare('DELETE FROM usuarios WHERE id=?'); $s->execute([$u['id']]); session_destroy(); resposta(true); }
 if ($acao === 'criar-pedido') { $u=usuarioLogado(); $d=entrada(); $itens=$d['itens']??[]; if(!$itens || !in_array($d['tipo_entrega']??'', ['Retirada','Entrega']) || !in_array($d['forma_pagamento']??'', ['PIX','Cartão','Dinheiro'])) resposta(false,['mensagem'=>'Confira os itens, entrega e pagamento.'],400); $taxa=0; if($d['tipo_entrega']==='Entrega'){$arquivo=__DIR__.'/taxa.txt';$taxa=file_exists($arquivo)?(float)file_get_contents($arquivo):7;} $total=0; $saboresPizza=count($itens)>1 && !empty($d['pizza_dois_sabores']); foreach($itens as $i){$s=$pdo->prepare('SELECT preco,categoria FROM cardapio WHERE id=? AND ativo=1');$s->execute([(int)$i['item_id']]);$p=$s->fetch(); if(!$p || (int)$i['quantidade']<1) resposta(false,['mensagem'=>'Um item do pedido não está disponível.'],400); $preco=(float)$p['preco']; if($saboresPizza && $p['categoria']==='Pizza') $preco=$preco/2; $total+=$preco*(int)$i['quantidade'];} $total+=$taxa; $pdo->beginTransaction(); $s=$pdo->prepare("INSERT INTO pedidos(usuario_id,status,tipo_entrega,taxa_entrega,valor_total,forma_pagamento) VALUES(?,'Pedido Recebido',?,?,?,?)");$s->execute([$u['id'],$d['tipo_entrega'],$taxa,$total,$d['forma_pagamento']]);$pedido=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO itens_pedido(pedido_id,item_id,quantidade,observacao) VALUES(?,?,?,?)');foreach($itens as $i)$s->execute([$pedido,(int)$i['item_id'],(int)$i['quantidade'],substr($i['observacao']??'',0,500)]);$pdo->commit();resposta(true,['pedido_id'=>$pedido,'total'=>$total]); }
 if ($acao === 'meus-pedidos' || $acao === 'todos-pedidos') { $u=$acao==='todos-pedidos'?administrador():usuarioLogado(); $sql='SELECT p.*,u.nome cliente FROM pedidos p JOIN usuarios u ON u.id=p.usuario_id'; if($acao==='meus-pedidos'){$s=$pdo->prepare($sql.' WHERE p.usuario_id=? ORDER BY p.id DESC');$s->execute([$u['id']]);}else{$s=$pdo->query($sql.' ORDER BY p.id DESC');} $lista=$s->fetchAll(); foreach($lista as &$p){$s=$pdo->prepare('SELECT ip.quantidade,ip.observacao,c.nome,c.categoria FROM itens_pedido ip JOIN cardapio c ON c.id=ip.item_id WHERE ip.pedido_id=?');$s->execute([$p['id']]);$p['itens']=$s->fetchAll();}resposta(true,['pedidos'=>$lista]); }
 if ($acao === 'atualizar-status') { administrador();$d=entrada();$permitidos=['Pedido Recebido','Em Preparo','Pronto','Saiu para Entrega','Finalizado','Cancelado'];if(!in_array($d['status']??'', $permitidos))resposta(false,['mensagem'=>'Status inválido.'],400);$motivo=$d['status']==='Cancelado'?trim($d['motivo']??''):null;if($d['status']==='Cancelado' && !$motivo)resposta(false,['mensagem'=>'Informe o motivo do cancelamento.'],400);$s=$pdo->prepare('UPDATE pedidos SET status=?,motivo_cancelamento=? WHERE id=?');$s->execute([$d['status'],$motivo,(int)$d['id']]);resposta(true,['mensagem'=>'Pedido atualizado.']); }
 if ($acao === 'salvar-produto') { administrador();$d=entrada();if(empty($d['nome'])||!in_array($d['categoria']??'', ['Pizza','Bebida'])||(float)($d['preco']??0)<=0)resposta(false,['mensagem'=>'Informe nome, categoria e preço válido.'],400);if(!empty($d['id'])){$s=$pdo->prepare('UPDATE cardapio SET nome=?,descricao=?,categoria=?,preco=?,ativo=1 WHERE id=?');$s->execute([$d['nome'],$d['descricao']??'',$d['categoria'],$d['preco'],$d['id']]);}else{$s=$pdo->prepare('INSERT INTO cardapio(nome,descricao,categoria,preco) VALUES(?,?,?,?)');$s->execute([$d['nome'],$d['descricao']??'',$d['categoria'],$d['preco']]);}resposta(true,['mensagem'=>'Produto salvo.']); }
 if ($acao === 'excluir-produto') { administrador();$d=entrada();$s=$pdo->prepare('UPDATE cardapio SET ativo=0 WHERE id=?');$s->execute([(int)$d['id']]);resposta(true,['mensagem'=>'Produto excluído do cardápio.']); }
 if ($acao === 'salvar-taxa') { administrador();$d=entrada();$valor=max(0,(float)($d['taxa']??0));file_put_contents(__DIR__.'/taxa.txt',(string)$valor);resposta(true,['mensagem'=>'Taxa atualizada.']); }
 if ($acao === 'novo-admin') { administrador();$d=entrada();if(strlen(trim($d['nome']??''))<3||!filter_var($d['email']??'',FILTER_VALIDATE_EMAIL)||strlen($d['senha']??'')<4)resposta(false,['mensagem'=>'Confira os dados.'],400);try{$s=$pdo->prepare('INSERT INTO usuarios(nome,email,senha,endereco,is_admin) VALUES(?,?,?,?,1)');$s->execute([$d['nome'],$d['email'],password_hash($d['senha'],PASSWORD_DEFAULT),$d['endereco']??'Cadastro administrativo']);}catch(PDOException $e){resposta(false,['mensagem'=>'E-mail já cadastrado.'],400);}resposta(true,['mensagem'=>'Administrador cadastrado.']); }
 resposta(false,['mensagem'=>'Ação não encontrada.'],404);
} catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); resposta(false,['mensagem'=>'Não foi possível concluir. Confira os dados e tente novamente.'],500); }
